[TestMethod]
public void PlaceholderValue_IsClearedAfterSuccessfulLaunch()
{
    SetSearchBox("issue-50175");
    this.Find<NavigationViewItem>("issue-50175").DoubleClick();
    var field = this.Find<TextBox>("issue50175");
    field.SetText("first-value");
    Assert.AreEqual("first-value", field.Text);
    this.PressKey(Key.Enter);
    Assert.IsNotNull(this.Find<TextBox>(By.AccessibilityId("MainSearchBox")));
    this.Find<NavigationViewItem>("issue-50175").DoubleClick();
    Assert.AreEqual(string.Empty, this.Find<TextBox>("issue50175").Text);
}
